// Cadência aprovada:
//  boas-vindas (email)  — 2 dias depois de marcar, só se lead total >= 10 dias
//  meio (whatsapp)      — a meio do intervalo, só se lead total >= 14 dias
//  reta final (email)   — 7 dias antes da sessão, só se lead total >= 7 dias
//  lead < 7 dias        — sem nutrição (a confirmação 24h já cobre)
// Máx. 1 toque por sessão por dia (prioridade: reta final > meio > boas-vindas).
// Os flags nutricao* na Sessao evitam repetições entre dias.
const DIA = 24 * 60 * 60 * 1000;
const agora = Date.now();

// Sem envios ao domingo (regra de timing da marca)
const diaSemana = new Date().toLocaleDateString('en-US', { timeZone: 'Europe/Lisbon', weekday: 'short' });
if (diaSemana === 'Sun') return [];

const sessoes = ($json.data || []).filter(s => s.estado === 'agendada' || s.estado === 'confirmada');
const out = [];

for (const s of sessoes) {
  const criadoEm = new Date(s.criadoEm).getTime();
  const dataSessao = new Date(s.data).getTime();
  if (dataSessao <= agora) continue;

  const leadDias = (dataSessao - criadoEm) / DIA;
  const diasAte = Math.ceil((dataSessao - agora) / DIA);
  const diasDesde = Math.floor((agora - criadoEm) / DIA);
  const meioDoCaminho = criadoEm + (dataSessao - criadoEm) / 2;

  let toque = null;
  if (!s.nutricao7dEnviado && leadDias >= 7 && diasAte <= 7 && diasAte >= 2) {
    toque = { tipo: 'retafinal', canal: 'email', flagField: 'nutricao7dEnviado' };
  } else if (!s.nutricao14dEnviado && leadDias >= 14 && diasAte > 8 && agora >= meioDoCaminho) {
    toque = { tipo: 'meio', canal: 'whatsapp', flagField: 'nutricao14dEnviado' };
  } else if (!s.nutricaoBoasVindasEnviado && leadDias >= 10 && diasDesde >= 2 && diasAte > 8) {
    toque = { tipo: 'boasvindas', canal: 'email', flagField: 'nutricaoBoasVindasEnviado' };
  }
  if (!toque) continue;

  const telefone = (((s.cliente && s.cliente.telefone) || '')).replace(/\D/g, '');
  const telefoneCompleto = telefone.length === 9 ? '351' + telefone : telefone;
  const emailCliente = (s.cliente && s.cliente.email) || null;
  const temWhatsapp = ((s.cliente && s.cliente.temWhatsapp) !== false) && telefoneCompleto.length > 0;

  // Sem WhatsApp: o toque 'meio' cai para email; sem WhatsApp nem email, ignora o toque
  let canalFinal = toque.canal;
  if (canalFinal === 'whatsapp' && !temWhatsapp) {
    if (!emailCliente) continue;
    canalFinal = 'email';
  }
  if (canalFinal === 'email' && !emailCliente) continue;

  out.push({ json: {
    sessaoId: s.id,
    clienteId: s.clienteId,
    nome: (s.cliente && s.cliente.nome) || '',
    primeiroNome: (((s.cliente && s.cliente.nome) || '').split(' ')[0]) || '',
    telefone: telefoneCompleto,
    servico: s.servico || 'a tua sessão',
    dataSessaoISO: s.data,
    hora: s.hora || '',
    diasAteSessao: diasAte,
    tipoToque: toque.tipo,
    canal: canalFinal,
    flagField: toque.flagField,
  } });
}

return out;

const c = $('Classificar Toques').item.json;
const perfil = $json.data || $json;
const primeiraVez = (perfil.totalSessoes ?? 0) === 0;
const email = perfil.email || null;

const dataFmt = new Date(c.dataSessaoISO).toLocaleDateString('pt-PT', { timeZone: 'Europe/Lisbon', weekday: 'long', day: '2-digit', month: 'long' });

const EXEMPLOS_REAIS_BEA = [
  '"Bom dia Catarina 😉 Iremos verificar as disponibilidades"',
  '"Bom dia 😊 pretende agendar ?"',
  '"Amanhã, sem problema algum 😉"',
  '"Olá 🌿 Obrigado por nos contactar! Na Essence Wellness acreditamos no cuidado personalizado. Diga-nos como podemos ajudar — seja para esclarecer dúvidas ou marcar a sua massagem, estamos ao seu dispôr."',
  '"Olá! Claro que sim 😊 Temos vouchers fisicos e digitais."',
  '"Agradeço Sofia, ás 18h é perfeito. Ate ja 😊"',
].join('\n');

const REGRAS_COMUNS = [
  'REGRAS ABSOLUTAS — baseadas em como a Bea escreve DE VERDADE no WhatsApp (exemplos reais abaixo), não num manual de marca abstrato:',
  EXEMPLOS_REAIS_BEA,
  '',
  '- Português europeu, tratamento por VOCÊ (a Bea trata sempre por você na prática: "pretende", "se desejar", "consegue") — NUNCA tratar por tu',
  '- Começa com uma saudação simples e direta: Bom dia / Olá [nome]',
  '- A cliente é mulher: usa sempre formas femininas quando relevante',
  '- Nunca mencionar que esta mensagem foi gerada automaticamente, por um sistema ou por inteligência artificial',
  '- Nunca mencionar preços, promoções, descontos ou urgência artificial',
  '- Nunca usar linguagem comercial agressiva (não percas, marca já, garante o teu lugar)',
  '- Nunca usar clichês de wellness/coach (a tua jornada, ouve o teu corpo, equilíbrio holístico, energia, essência da natureza)',
  '- Nunca usar superlativos vazios (incrível, fantástico, revolucionário, transformador)',
  '- Emojis à vontade no estilo dos exemplos (🌿😊😉🤍), sem exagerar — 1 a 2 por mensagem',
  '- Nunca colar gerúndios no fim das frases (proporcionando, permitindo, promovendo, garantindo)',
  '- Nunca personificar o corpo (o teu corpo pede, o teu corpo agradece)',
  '- Nunca citar fontes vagas (estudos demonstram, especialistas afirmam)',
  '- Nunca abrir com frases genéricas (No mundo de hoje, Cada vez mais)',
  '- Nunca fechar com Em suma, Lembra-te, ou frases motivacionais genéricas',
  '- Evita travessões; usa vírgula, dois pontos ou ponto final',
  '- Frases curtas e diretas, como nos exemplos reais — nada de parágrafos longos e floreados',
  '- Sê concreta: quantidades, momentos do dia e gestos reais em vez de conselhos abstratos',
].join('\n');

const FORMATO_EMAIL = 'FORMATO DE SAÍDA\nDevolve APENAS um objeto JSON válido, sem markdown e sem blocos de código, com exatamente esta estrutura:\n{"assunto": "...", "corpo": "...", "motivo": "resumo curto do angulo escolhido"}';
const FORMATO_WA = 'FORMATO DE SAÍDA\nDevolve APENAS um objeto JSON válido, sem markdown e sem blocos de código:\n{"corpo": "...", "motivo": "resumo curto do angulo escolhido"}';

const SYSTEMS = {
  boasvindas: 'Escreves como a Bea, dona da Essence Wellness (centro de massagens em Vila Nova de Gaia), um email de boas-vindas para uma cliente que acabou de marcar uma sessão, mas a sessão só acontece daqui a várias semanas.\n\nO objetivo é fazer a cliente sentir-se bem-vinda, no MESMO estilo direto e caloroso da Bea. Nunca vendes, nunca pressionas, nunca soas a lembrete administrativo.\n\n' + REGRAS_COMUNS + '\n- Assina no fim como Essence Wellness\n- Escolhe UM único ângulo: boas-vindas e confirmação da marcação; o que esperar ao chegar; desconstruir o nervosismo de estreia (só se for primeira vez); a personalização da sessão\n- Corpo do email: curto e direto (50-100 palavras), sem listas nem bullet points\n- Um convite simples no fim para tirar dúvidas\n\n' + FORMATO_EMAIL,
  meio: 'Escreves como a Bea, dona da Essence Wellness (centro de massagens em Vila Nova de Gaia), uma mensagem de WhatsApp para uma cliente que já marcou sessão, a meio do intervalo de espera até à data marcada.\n\nEsta mensagem NÃO é sobre a marcação em si - é um toque de presença leve durante a espera. Não perguntes se vai confirmar, não menciones logística.\n\n' + REGRAS_COMUNS + '\n- Máximo 3 frases no corpo da mensagem\n- Sem assinatura no fim — a Bea nunca assina as mensagens de WhatsApp\n- Proibido frases floreadas ou poéticas vazias sobre natureza/energia/essência (ex: "a essência da natureza está em te rodear") - são clichés sem conteúdo real\n- ESCOLHE EXATAMENTE UMA destas dicas reais (baseadas em recomendações de terapeutas de massagem) e transforma-a numa frase pessoal e direta - NUNCA inventes uma dica diferente destas:\n  1. Beber um copo extra de água hoje - ajuda o corpo a preparar-se e, depois da massagem, a eliminar as toxinas libertadas durante a sessão\n  2. Um alongamento leve aos ombros ou às costas antes de deitar, para soltar tensão acumulada\n  3. Dois minutos de respiração lenta antes de adormecer, para acalmar o sistema nervoso\n  4. Um banho ou duche morno na noite anterior à sessão, que ajuda os músculos a relaxar\n  5. Evitar uma refeição pesada nas horas antes da sessão - o corpo relaxa melhor com o estômago leve\n  6. Chegar uns minutos mais cedo no dia da sessão, só para abrandar antes de começar\n- Pensa em qual das seis faz mais sentido dado o número de dias até à sessão (dicas 1, 4 e 5 fazem mais sentido perto da data; 2 e 3 servem em qualquer altura)\n- Proibido terminar com uma pergunta genérica tipo "o que está a fazer para se sentir bem" - fecha sempre com uma frase calorosa e específica, sem pedir resposta\n\n' + FORMATO_WA,
  retafinal: 'Escreves como a Bea, dona da Essence Wellness (centro de massagens em Vila Nova de Gaia), o email de preparação enviado 7 dias antes da sessão marcada.\n\nO objetivo é ajudar a cliente a chegar preparada e tranquila, resolver dúvidas logísticas - sem repetir ângulos já usados em contactos anteriores.\n\n' + REGRAS_COMUNS + '\n- Assina no fim como Essence Wellness\n- Inclui pelo menos UMA informação prática real: morada Av. da República nº 2208, Piso 2, Vila Nova de Gaia; chegar com alguns minutos de antecedência; roupa confortável; ou não encher a agenda logo a seguir à sessão\n- Escolhe UM ângulo: o que trazer/vestir; como chegar; o que esperar passo a passo; não encher a agenda a seguir; se primeira vez, reforço tranquilizador\n- Corpo do email: curto e direto (80-130 palavras), sem listas nem bullet points\n- Um convite simples no fim\n\n' + FORMATO_EMAIL,
};

const userPrompt = [
  'Escreve a mensagem para esta cliente da Essence Wellness:',
  '',
  'Nome: ' + c.primeiroNome,
  'Serviço marcado: ' + c.servico,
  'Data da sessão: ' + dataFmt + (c.hora ? ' às ' + c.hora : ''),
  'Dias até à sessão: ' + c.diasAteSessao,
  'Primeira vez na Essence: ' + (primeiraVez ? 'sim' : 'não'),
  '',
  'Personaliza com o nome e o serviço sem forçar. Devolve apenas o JSON pedido.',
].join('\n');

// Sem email válido não há como enviar toques de email — saltar
if (c.canal === 'email' && !email) return [];

return [{ json: {
  systemPrompt: SYSTEMS[c.tipoToque],
  userPrompt,
  canal: c.canal,
  tipoToque: c.tipoToque,
  flagField: c.flagField,
  sessaoId: c.sessaoId,
  clienteId: c.clienteId,
  primeiroNome: c.primeiroNome,
  telefone: c.telefone,
  email,
} }];

const prep = $('Preparar Prompt Nutrição').item.json;
const raw = ($json.content && $json.content[0] && $json.content[0].text) || '{}';

let d;
try {
  const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  d = JSON.parse(clean);
} catch (e) {
  throw new Error('Erro ao parsear JSON do Groq (' + prep.tipoToque + '): ' + e.message);
}

const corpo = (d.corpo || '').trim();
if (!corpo) throw new Error('Groq devolveu corpo vazio para ' + prep.tipoToque);

// Email: embrulhar o corpo no template da marca (mesmo estilo do email de onboarding)
let emailHtml = null;
if (prep.canal === 'email') {
  const paragrafos = corpo.split(/\n\n+/).map(p => '<p style="margin:0 0 18px;">' + p.replace(/\n/g, '<br>') + '</p>').join('');
  emailHtml = '<!DOCTYPE html><html><body style="margin:0;padding:0;background-color:#ede7e3;"><table width="100%" border="0" cellspacing="0" cellpadding="0" style="background-color:#ede7e3;padding:40px 20px;"><tr><td align="center"><table width="100%" border="0" cellspacing="0" cellpadding="0" style="max-width:600px;background-color:#ffffff;border-top:4px solid #c9a66b;border-radius:4px;padding:40px;"><tr><td align="center" style="padding-bottom:30px;"><h1 style="margin:0;font-family:serif;color:#1c1c1c;font-size:24px;font-weight:normal;letter-spacing:1px;">Essence Wellness</h1></td></tr><tr><td style="font-family:Helvetica,Arial,sans-serif;color:#6d6d6d;font-size:16px;line-height:1.8;">' + paragrafos + '</td></tr></table></td></tr></table></body></html>';
}

return [{ json: {
  canal: prep.canal,
  tipoToque: prep.tipoToque,
  flagField: prep.flagField,
  sessaoId: prep.sessaoId,
  clienteId: prep.clienteId,
  telefone: prep.telefone,
  email: prep.email,
  assunto: d.assunto || 'Uma nota da Essence Wellness',
  corpo,
  emailHtml,
  motivo: (d.motivo || '').slice(0, 300) || ('Nutrição pré-sessão — toque ' + prep.tipoToque),
} }];
